#!/usr/bin/env python3
"""Compile canonical AI instructions into provider-specific views."""

from __future__ import annotations

import argparse
import difflib
import json
import os
import re
import sys
from dataclasses import dataclass
from pathlib import Path


GENERATED_MARKER = "<!-- GENERATED BY omnigento/bin/sync_ai_instructions.py; DO NOT EDIT DIRECTLY -->"
LEGACY_GENERATED_MARKERS = (
    "<!-- GENERATED BY instruction-seed/bin/sync_ai_instructions.py; DO NOT EDIT DIRECTLY -->",
)
GENERATED_MARKERS = (GENERATED_MARKER, *LEGACY_GENERATED_MARKERS)
BEGIN_BLOCK = "<!-- BEGIN GENERATED INSTRUCTIONS -->"
END_BLOCK = "<!-- END GENERATED INSTRUCTIONS -->"
SCAFFOLD_MARKER = "<!-- omnigento scaffold -->"
LEGACY_SCAFFOLD_MARKERS = ("<!-- instruction-seed scaffold -->",)
SCAFFOLD_MARKERS = (SCAFFOLD_MARKER, *LEGACY_SCAFFOLD_MARKERS)
REPO_ROOT = Path(__file__).resolve().parents[2]
CANONICAL_DIR = REPO_ROOT / ".github" / "instructions"
SKILLS_DIR = CANONICAL_DIR / "skills"


@dataclass(frozen=True)
class Topic:
    stem: str
    path: Path
    rel_path: str
    description: str
    apply_to: str | None
    body: str
    kind: str

    @property
    def summary(self) -> str:
        return summarize_description(self.description)

    @property
    def title(self) -> str:
        match = re.search(r"^#\s+(.+)$", self.body, re.MULTILINE)
        if match:
            return match.group(1).strip()
        return self.stem.replace("-", " ").title()

    @property
    def apply_parts(self) -> list[str]:
        if not self.apply_to:
            return []
        return [part.strip() for part in self.apply_to.split(",") if part.strip()]


@dataclass(frozen=True)
class AuditFinding:
    level: str
    code: str
    path: str
    message: str


@dataclass
class AuditReport:
    findings: list[AuditFinding]

    def add(self, level: str, code: str, path: Path | str, message: str) -> None:
        if isinstance(path, Path):
            path_text = repo_rel(path)
        else:
            path_text = path
        self.findings.append(AuditFinding(level=level, code=code, path=path_text, message=message))

    def has_errors(self) -> bool:
        return any(finding.level == "ERROR" for finding in self.findings)


def repo_rel(path: Path) -> str:
    return path.relative_to(REPO_ROOT).as_posix()


def yaml_scalar(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in {'"', "'"}:
        return value[1:-1]
    return value


def parse_frontmatter(path: Path) -> tuple[dict[str, str], str]:
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        raise ValueError(f"{repo_rel(path)} is missing YAML frontmatter")

    end = None
    for index, line in enumerate(lines[1:], start=1):
        if line.strip() == "---":
            end = index
            break
    if end is None:
        raise ValueError(f"{repo_rel(path)} has unterminated YAML frontmatter")

    data: dict[str, str] = {}
    for raw in lines[1:end]:
        if not raw.strip() or raw.lstrip().startswith("#"):
            continue
        if ":" not in raw:
            raise ValueError(f"{repo_rel(path)} has unsupported frontmatter line: {raw}")
        key, value = raw.split(":", 1)
        data[key.strip()] = yaml_scalar(value)

    body = "\n".join(lines[end + 1 :]).strip() + "\n"
    return data, body


def topic_stem(path: Path) -> str:
    suffix = ".instructions.md"
    name = path.name
    if not name.endswith(suffix):
        raise ValueError(f"{repo_rel(path)} must end with {suffix}")
    return name[: -len(suffix)]


def load_topics() -> tuple[list[Topic], list[Topic], list[Topic]]:
    topics: list[Topic] = []
    stems: dict[str, Path] = {}
    paths = sorted(CANONICAL_DIR.glob("*.instructions.md")) + sorted(SKILLS_DIR.glob("*.instructions.md"))
    for path in paths:
        frontmatter, body = parse_frontmatter(path)
        stem = topic_stem(path)
        if stem in stems:
            raise ValueError(f"duplicate canonical stem {stem}: {repo_rel(stems[stem])} and {repo_rel(path)}")
        stems[stem] = path

        description = frontmatter.get("description", "").strip()
        if not description:
            raise ValueError(f"{repo_rel(path)} requires non-empty description frontmatter")

        apply_to = frontmatter.get("applyTo")
        if apply_to is not None:
            apply_to = apply_to.strip()
            if not apply_to:
                raise ValueError(f"{repo_rel(path)} has empty applyTo")

        is_skill = path.parent == SKILLS_DIR
        if is_skill and apply_to:
            raise ValueError(f"{repo_rel(path)} is under skills/ and must not have applyTo")

        if is_skill:
            kind = "on-request"
        elif apply_to:
            kind = "file-scoped"
        else:
            kind = "topic-based"

        topics.append(
            Topic(
                stem=stem,
                path=path,
                rel_path=repo_rel(path),
                description=description,
                apply_to=apply_to,
                body=body,
                kind=kind,
            )
        )

    file_scoped = [topic for topic in topics if topic.kind == "file-scoped"]
    topic_based = [topic for topic in topics if topic.kind == "topic-based"]
    on_request = [topic for topic in topics if topic.kind == "on-request"]
    return file_scoped, topic_based, on_request


def summarize_description(description: str) -> str:
    summary = re.split(r"\s+Use when\b", description, maxsplit=1)[0].strip()
    return summary.rstrip(".")


def quote_yaml(value: str) -> str:
    return '"' + value.replace("\\", "\\\\").replace('"', '\\"') + '"'


def split_apply_to(apply_to: str) -> list[str]:
    return [part.strip() for part in apply_to.split(",") if part.strip()]


def clean_directory_root(glob: str) -> str | None:
    glob = glob.strip().lstrip("/")
    if not glob or glob.startswith("**"):
        return None

    wildcard_positions = [pos for pos in (glob.find("*"), glob.find("?"), glob.find("[")) if pos >= 0]
    if wildcard_positions:
        prefix = glob[: min(wildcard_positions)]
    else:
        prefix = glob

    if prefix.endswith("/"):
        root = prefix.rstrip("/")
        return root or None

    if "/" not in prefix.rstrip("/"):
        if glob.endswith("/**"):
            return prefix.rstrip("/")
        return None

    root = prefix.rsplit("/", 1)[0]
    root = root.strip("/")
    if not root or root == ".":
        return None
    return root


def directory_roots(topic: Topic) -> list[str]:
    roots: list[str] = []
    for part in topic.apply_parts:
        root = clean_directory_root(part)
        if root and root not in roots:
            roots.append(root)
    return roots


def is_ancestor_or_same(parent: str, child: str) -> bool:
    return parent == child or child.startswith(parent.rstrip("/") + "/")


def rewrite_markdown_links(body: str, source: Path, output: Path) -> str:
    source_dir = source.parent
    output_dir = output.parent

    def replace(match: re.Match[str]) -> str:
        text = match.group(1)
        target = match.group(2)
        if (
            target.startswith("#")
            or re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", target)
            or target.startswith("/")
        ):
            return match.group(0)
        if target.startswith("<") and target.endswith(">"):
            inner = target[1:-1]
            if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", inner) or inner.startswith(("#", "/")):
                return match.group(0)
            target = inner
            wrapped = True
        else:
            wrapped = False
        if target.startswith("`"):
            return match.group(0)

        resolved = (source_dir / target).resolve()
        if not resolved.exists():
            return match.group(0)
        try:
            rewritten = os.path.relpath(resolved, output_dir).replace(os.sep, "/")
        except ValueError:
            return match.group(0)
        if wrapped:
            rewritten = f"<{rewritten}>"
        return f"[{text}]({rewritten})"

    rewritten_lines: list[str] = []
    in_fence = False
    fence_marker = ""
    for line in body.splitlines(keepends=True):
        stripped = line.lstrip()
        fence_match = re.match(r"(```+|~~~+)", stripped)
        if fence_match:
            marker = fence_match.group(1)
            if not in_fence:
                in_fence = True
                fence_marker = marker[:3]
            elif marker.startswith(fence_marker):
                in_fence = False
                fence_marker = ""
            rewritten_lines.append(line)
            continue
        if in_fence:
            rewritten_lines.append(line)
            continue
        rewritten_lines.append(re.sub(r"\[([^\]]+)\]\(([^)]+)\)", replace, line))
    return "".join(rewritten_lines)


def inline_body(topic: Topic, output: Path) -> str:
    return rewrite_markdown_links(topic.body, topic.path, output).rstrip() + "\n"


def generated_after_frontmatter(frontmatter: str, body: str) -> str:
    return f"{frontmatter.rstrip()}\n{GENERATED_MARKER}\n\n{body.rstrip()}\n"


def cursor_rule(topic: Topic) -> str:
    path = REPO_ROOT / ".cursor" / "rules" / f"{topic.stem}.mdc"
    if topic.kind == "file-scoped":
        frontmatter = f"---\nglobs: {quote_yaml(topic.apply_to or '')}\nalwaysApply: false\n---"
    else:
        frontmatter = f"---\ndescription: {quote_yaml(topic.description)}\nalwaysApply: false\n---"
    body = f"Canonical source: `{topic.rel_path}`\n\n" + inline_body(topic, path)
    return generated_after_frontmatter(frontmatter, body)


def cursor_topic_index(topics: list[Topic]) -> str:
    lines = [
        "---",
        "alwaysApply: false",
        "---",
        GENERATED_MARKER,
        "",
        "Topic-based rules live in `.github/instructions/`. Read the relevant file when the topic comes up:",
        "",
    ]
    lines.extend(topic_line(topic) for topic in topics)
    return "\n".join(lines).rstrip() + "\n"


def claude_rule(topic: Topic) -> str:
    path = REPO_ROOT / ".claude" / "rules" / f"{topic.stem}.md"
    path_lines = "\n".join(f'  - "{part}"' for part in split_apply_to(topic.apply_to or ""))
    frontmatter = f"---\npaths:\n{path_lines}\n---"
    body = f"Canonical source: `{topic.rel_path}`\n\n" + inline_body(topic, path)
    return generated_after_frontmatter(frontmatter, body)


def claude_topic_index(topics: list[Topic]) -> str:
    lines = [
        GENERATED_MARKER,
        "",
        "Topic-based rules live in `.github/instructions/`. Read the relevant file when the topic comes up:",
        "",
    ]
    lines.extend(topic_line(topic) for topic in topics)
    return "\n".join(lines).rstrip() + "\n"


def claude_skill(topic: Topic) -> str:
    path = REPO_ROOT / ".claude" / "skills" / topic.stem / "SKILL.md"
    frontmatter = f"---\nname: {topic.stem}\ndescription: {topic.description}\n---"
    body = f"Canonical source: `{topic.rel_path}`\n\n" + inline_body(topic, path)
    return generated_after_frontmatter(frontmatter, body)


def topic_line(topic: Topic) -> str:
    return f"- **{topic.summary}** -> `{topic.rel_path}`"


def root_agents(topic_based: list[Topic], on_request: list[Topic]) -> str:
    lines = [
        GENERATED_MARKER,
        "",
        "# Rust Server Project",
        "",
        "Read and follow `.github/copilot-instructions.md` - it is the provider-neutral hub for all project rules.",
        "",
        "Canonical instruction files live in `.github/instructions/`. Generated provider views may inline canonical content for deterministic loading, but canonical source remains `.github/instructions/`.",
        "",
        "`AGENTS.md` is the shared agent-markdown view for tools that read this convention, including Cursor and Codex. File-scoped routing lives in provider path metadata and nested `AGENTS.md` files.",
        "",
        "## Topic-based topics",
        "",
    ]
    lines.extend(topic_line(topic) for topic in topic_based)
    lines.extend(["", "## On-request actions", ""])
    if on_request:
        lines.extend(topic_line(topic) for topic in on_request)
    else:
        lines.append("- None")
    return "\n".join(lines).rstrip() + "\n"


def claude_root(topic_based: list[Topic]) -> str:
    lines = [
        GENERATED_MARKER,
        "",
        "# Rust Server Project",
        "",
        "Read and follow `.github/copilot-instructions.md` - it is the provider-neutral hub for all project rules.",
        "",
        "Generated Claude provider views live in `.claude/rules/` and `.claude/skills/`. Canonical source remains `.github/instructions/`.",
        "",
        "For topic-based rules, read the relevant file when the topic comes up:",
        "",
    ]
    lines.extend(topic_line(topic) for topic in topic_based)
    return "\n".join(lines).rstrip() + "\n"


def nested_agents(file_scoped: list[Topic]) -> dict[Path, str]:
    root_to_topics: dict[str, list[Topic]] = {}
    all_roots = sorted({root for topic in file_scoped for root in directory_roots(topic)})
    for root in all_roots:
        applicable: list[Topic] = []
        for topic in file_scoped:
            if any(is_ancestor_or_same(topic_root, root) for topic_root in directory_roots(topic)):
                applicable.append(topic)
        if applicable:
            root_to_topics[root] = sorted(applicable, key=lambda topic: topic.stem)

    outputs: dict[Path, str] = {}
    for root, topics in root_to_topics.items():
        path = REPO_ROOT / root / "AGENTS.md"
        title = root.replace("/", " ").replace(".", "").title() or "Scoped"
        lines = [
            GENERATED_MARKER,
            "",
            f"# {title} Agent Rules",
            "",
            "Generated file-scoped rules for this directory. Canonical source remains `.github/instructions/`.",
            "",
        ]
        for index, topic in enumerate(topics):
            if index:
                lines.append("---")
                lines.append("")
            rel_source = os.path.relpath(topic.path, path.parent).replace(os.sep, "/")
            lines.append(f"## {topic.title}")
            lines.append("")
            lines.append(f"Canonical source: `{rel_source}`")
            lines.append("")
            lines.append(inline_body(topic, path).rstrip())
            lines.append("")
        outputs[path] = "\n".join(lines).rstrip() + "\n"
    return outputs


def reference_docs_section(all_topics: list[Topic]) -> str:
    lines = [
        BEGIN_BLOCK,
        "",
        "All detailed rules live in `.github/instructions/`. Generated provider views may inline canonical content for deterministic path/request loading; topic-based indexes stay compact by default.",
        "",
        "| File | Covers | Auto-loads for |",
        "|------|--------|----------------|",
    ]
    for topic in all_topics:
        if topic.kind == "on-request":
            auto = "On-request"
        elif topic.kind == "topic-based":
            auto = "On-demand"
        else:
            auto = f"`{topic.apply_to}`"
        lines.append(f"| [{Path(topic.rel_path).name}]({topic.rel_path}) | {topic.summary} | {auto} |")
    lines.extend(["", END_BLOCK])
    return "\n".join(lines)


def update_copilot(existing: str, all_topics: list[Topic]) -> str:
    section = reference_docs_section(all_topics)
    if BEGIN_BLOCK in existing and END_BLOCK in existing:
        pattern = re.compile(re.escape(BEGIN_BLOCK) + r".*?" + re.escape(END_BLOCK), re.DOTALL)
        return pattern.sub(section, existing, count=1)

    replacement = "## Reference Docs\n\n" + section + "\n"
    match = re.search(r"^## Reference Docs\s*$", existing, re.MULTILINE)
    if not match:
        return existing.rstrip() + "\n\n---\n\n" + replacement

    next_section = re.search(r"^\s*---\s*$\n\n^## ", existing[match.end() :], re.MULTILINE)
    if next_section:
        start = match.start()
        end = match.end() + next_section.start()
        return existing[:start] + replacement.rstrip() + "\n\n" + existing[end:]

    next_heading = re.search(r"^## ", existing[match.end() :], re.MULTILINE)
    if next_heading:
        start = match.start()
        end = match.end() + next_heading.start()
        return existing[:start] + replacement + "\n" + existing[end:]

    return existing[: match.start()] + replacement


def generated_outputs(file_scoped: list[Topic], topic_based: list[Topic], on_request: list[Topic]) -> dict[Path, str]:
    outputs: dict[Path, str] = {}
    for topic in file_scoped:
        outputs[REPO_ROOT / ".cursor" / "rules" / f"{topic.stem}.mdc"] = cursor_rule(topic)
        outputs[REPO_ROOT / ".claude" / "rules" / f"{topic.stem}.md"] = claude_rule(topic)
    for topic in on_request:
        outputs[REPO_ROOT / ".cursor" / "rules" / f"{topic.stem}.mdc"] = cursor_rule(topic)
        outputs[REPO_ROOT / ".claude" / "skills" / topic.stem / "SKILL.md"] = claude_skill(topic)
    outputs[REPO_ROOT / ".cursor" / "rules" / "topic-index.mdc"] = cursor_topic_index(topic_based)
    outputs[REPO_ROOT / ".claude" / "rules" / "topic-index.md"] = claude_topic_index(topic_based)
    outputs[REPO_ROOT / "AGENTS.md"] = root_agents(topic_based, on_request)
    outputs[REPO_ROOT / "CLAUDE.md"] = claude_root(topic_based)
    outputs.update(nested_agents(file_scoped))

    copilot = REPO_ROOT / ".github" / "copilot-instructions.md"
    if copilot.exists():
        existing = copilot.read_text(encoding="utf-8")
    else:
        existing = "# Rust Server Project - AI Instructions\n\n## Reference Docs\n\n"
    all_topics = sorted(file_scoped + topic_based + on_request, key=lambda topic: topic.rel_path)
    outputs[copilot] = update_copilot(existing, all_topics)
    return outputs


def owned_generated_files() -> set[Path]:
    candidates: list[Path] = []
    for base, pattern in [
        (REPO_ROOT / ".cursor" / "rules", "*.mdc"),
        (REPO_ROOT / ".claude" / "rules", "*.md"),
        (REPO_ROOT / ".claude" / "skills", "*/SKILL.md"),
        (REPO_ROOT, "AGENTS.md"),
        (REPO_ROOT, "CLAUDE.md"),
    ]:
        if base.exists():
            candidates.extend(base.glob(pattern))
    if REPO_ROOT.exists():
        candidates.extend(path for path in REPO_ROOT.glob("**/AGENTS.md") if ".git" not in path.parts)

    owned: set[Path] = set()
    for path in candidates:
        try:
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        if any(marker in text for marker in GENERATED_MARKERS):
            owned.add(path)
    return owned


def diff_text(path: Path, expected: str) -> str:
    old = path.read_text(encoding="utf-8") if path.exists() else ""
    return "".join(
        difflib.unified_diff(
            old.splitlines(keepends=True),
            expected.splitlines(keepends=True),
            fromfile=f"a/{repo_rel(path)}",
            tofile=f"b/{repo_rel(path)}",
        )
    )


def stale_generated(outputs: dict[Path, str]) -> set[Path]:
    return owned_generated_files() - set(outputs)


def run_check(outputs: dict[Path, str]) -> int:
    drift: list[str] = []
    for path, expected in sorted(outputs.items(), key=lambda item: repo_rel(item[0])):
        actual = path.read_text(encoding="utf-8") if path.exists() else None
        if actual != expected:
            drift.append(repo_rel(path))
    stale = sorted(stale_generated(outputs), key=repo_rel)
    if not drift and not stale:
        print("instruction sync check passed")
        return 0
    if drift:
        print("instruction sync drift:")
        for item in drift:
            print(f"  changed/missing: {item}")
    if stale:
        print("stale generated files:")
        for item in stale:
            print(f"  stale: {repo_rel(item)}")
    return 1


def strip_inline_code(line: str) -> str:
    return re.sub(r"`[^`]*`", "", line)


def markdown_links_outside_fences(text: str) -> list[str]:
    links: list[str] = []
    in_fence = False
    fence_marker = ""
    for line in text.splitlines():
        stripped = line.lstrip()
        fence_match = re.match(r"(```+|~~~+)", stripped)
        if fence_match:
            marker = fence_match.group(1)
            if not in_fence:
                in_fence = True
                fence_marker = marker[:3]
            elif marker.startswith(fence_marker):
                in_fence = False
                fence_marker = ""
            continue
        if in_fence:
            continue

        searchable = strip_inline_code(line)
        for match in re.finditer(r"(?<!!)\[[^\]]+\]\(([^)]+)\)", searchable):
            target = match.group(1).strip()
            if target.startswith("<") and target.endswith(">"):
                target = target[1:-1].strip()
            if target:
                links.append(target)
    return links


def is_local_markdown_reference(target: str) -> bool:
    if (
        target.startswith("#")
        or target.startswith("/")
        or re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", target)
    ):
        return False
    return True


def markdown_target_exists(source: Path, target: str) -> bool:
    target = target.split("#", 1)[0]
    if not target:
        return True
    return (source.parent / target).resolve().exists() or (REPO_ROOT / target).resolve().exists()


def read_text_if_exists(path: Path) -> str:
    if not path.exists():
        return ""
    return path.read_text(encoding="utf-8")


def extract_frontmatter(text: str) -> tuple[dict[str, str], str]:
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return {}, text

    end = None
    for index, line in enumerate(lines[1:], start=1):
        if line.strip() == "---":
            end = index
            break
    if end is None:
        return {}, text

    data: dict[str, str] = {}
    for raw in lines[1:end]:
        if not raw.strip() or raw.lstrip().startswith("#") or ":" not in raw:
            continue
        key, value = raw.split(":", 1)
        data[key.strip()] = yaml_scalar(value)
    return data, "\n".join(lines[end + 1 :])


def section_body(text: str, heading: str) -> str:
    pattern = re.compile(rf"^##\s+{re.escape(heading)}\s*$\n?(.*?)(?=^##\s+|\Z)", re.MULTILINE | re.DOTALL)
    match = pattern.search(text)
    return match.group(1) if match else ""


def canonical_stems(file_scoped: list[Topic], topic_based: list[Topic], on_request: list[Topic]) -> tuple[set[str], set[str]]:
    top_level = {topic.stem for topic in file_scoped + topic_based}
    skills = {topic.stem for topic in on_request}
    return top_level, skills


def audit_dangling_links(report: AuditReport) -> None:
    targets = [
        REPO_ROOT / ".github" / "copilot-instructions.md",
        REPO_ROOT / ".cursor" / "rules" / "topic-index.mdc",
        REPO_ROOT / ".claude" / "rules" / "topic-index.md",
        REPO_ROOT / "AGENTS.md",
        REPO_ROOT / "CLAUDE.md",
    ]
    for source in targets:
        if not source.exists():
            report.add("ERROR", "missing-provider-entry", source, "provider entry point is missing")
            continue
        for target in sorted(set(markdown_links_outside_fences(source.read_text(encoding="utf-8")))):
            if not is_local_markdown_reference(target):
                continue
            if not markdown_target_exists(source, target):
                report.add("ERROR", "dangling-reference", source, f"link target does not exist: {target}")


def audit_provider_stem_parity(
    report: AuditReport,
    file_scoped: list[Topic],
    topic_based: list[Topic],
    on_request: list[Topic],
) -> None:
    top_level, skills = canonical_stems(file_scoped, topic_based, on_request)

    cursor_dir = REPO_ROOT / ".cursor" / "rules"
    if cursor_dir.exists():
        for path in sorted(cursor_dir.glob("*.mdc")):
            if path.name == "topic-index.mdc":
                continue
            if path.stem not in top_level and path.stem not in skills:
                report.add("ERROR", "orphan-provider-pointer", path, "Cursor rule stem has no matching canonical instruction")

    claude_rules = REPO_ROOT / ".claude" / "rules"
    if claude_rules.exists():
        for path in sorted(claude_rules.glob("*.md")):
            if path.name == "topic-index.md":
                continue
            if path.stem not in top_level:
                report.add("ERROR", "orphan-provider-pointer", path, "Claude rule stem has no matching top-level canonical instruction")

    claude_skills = REPO_ROOT / ".claude" / "skills"
    if claude_skills.exists():
        for path in sorted(claude_skills.glob("*/SKILL.md")):
            stem = path.parent.name
            if stem not in skills:
                report.add("ERROR", "orphan-provider-pointer", path, "Claude skill folder has no matching canonical skill instruction")


def audit_scaffold_residue(report: AuditReport) -> None:
    candidates = [
        REPO_ROOT / ".github" / "copilot-instructions.md",
        REPO_ROOT / "AGENTS.md",
        REPO_ROOT / "CLAUDE.md",
    ]
    for base, pattern in [
        (REPO_ROOT / ".cursor" / "rules", "*.mdc"),
        (REPO_ROOT / ".claude" / "rules", "*.md"),
        (REPO_ROOT / ".claude" / "skills", "*/SKILL.md"),
    ]:
        if base.exists():
            candidates.extend(base.glob(pattern))

    for path in sorted(set(candidates), key=repo_rel):
        if not path.exists():
            continue
        text = path.read_text(encoding="utf-8")
        if any(marker in text for marker in SCAFFOLD_MARKERS):
            report.add("ERROR", "scaffold-residue", path, "omnigento scaffold marker remains")


def audit_frontmatter(
    report: AuditReport,
    file_scoped: list[Topic],
    on_request: list[Topic],
) -> None:
    cursor_topic = REPO_ROOT / ".cursor" / "rules" / "topic-index.mdc"
    topic_frontmatter, _ = extract_frontmatter(read_text_if_exists(cursor_topic))
    if cursor_topic.exists():
        if topic_frontmatter.get("alwaysApply") != "false":
            report.add("ERROR", "frontmatter-drift", cursor_topic, "topic index must use alwaysApply: false")
        if "globs" in topic_frontmatter:
            report.add("ERROR", "frontmatter-drift", cursor_topic, "topic index must not define globs")

    claude_topic = REPO_ROOT / ".claude" / "rules" / "topic-index.md"
    if claude_topic.exists():
        claude_frontmatter, _ = extract_frontmatter(claude_topic.read_text(encoding="utf-8"))
        if claude_frontmatter:
            report.add("ERROR", "frontmatter-drift", claude_topic, "Claude topic index must not have YAML frontmatter")

    for topic in file_scoped:
        path = REPO_ROOT / ".cursor" / "rules" / f"{topic.stem}.mdc"
        frontmatter, _ = extract_frontmatter(read_text_if_exists(path))
        if not path.exists():
            continue
        if frontmatter.get("globs") != (topic.apply_to or ""):
            report.add("ERROR", "frontmatter-drift", path, "file-scoped Cursor globs must match canonical applyTo")
        if frontmatter.get("alwaysApply") != "false":
            report.add("ERROR", "frontmatter-drift", path, "Cursor generated rule must use alwaysApply: false")

    for topic in on_request:
        path = REPO_ROOT / ".cursor" / "rules" / f"{topic.stem}.mdc"
        frontmatter, _ = extract_frontmatter(read_text_if_exists(path))
        if not path.exists():
            continue
        if "globs" in frontmatter:
            report.add("ERROR", "frontmatter-drift", path, "on-request Cursor rule must not define globs")
        if frontmatter.get("description") != topic.description:
            report.add("ERROR", "frontmatter-drift", path, "on-request Cursor description must match canonical description")


def audit_index_wording(
    report: AuditReport,
    topic_based: list[Topic],
    on_request: list[Topic],
) -> None:
    cursor_topic = REPO_ROOT / ".cursor" / "rules" / "topic-index.mdc"
    claude_topic = REPO_ROOT / ".claude" / "rules" / "topic-index.md"
    agents = REPO_ROOT / "AGENTS.md"
    copilot = REPO_ROOT / ".github" / "copilot-instructions.md"

    cursor_text = read_text_if_exists(cursor_topic)
    claude_text = read_text_if_exists(claude_topic)
    agents_text = read_text_if_exists(agents)
    agents_topics = section_body(agents_text, "Topic-based topics")
    agents_actions = section_body(agents_text, "On-request actions")
    copilot_text = read_text_if_exists(copilot)

    for topic in topic_based:
        expected = topic_line(topic)
        for path, text in [(cursor_topic, cursor_text), (claude_topic, claude_text)]:
            if path.exists() and expected not in text:
                report.add("ERROR", "index-wording-drift", path, f"missing canonical topic line: {expected}")
        if agents.exists() and expected not in agents_topics:
            report.add("ERROR", "index-wording-drift", agents, f"missing Topic-based topic line: {expected}")

    for topic in on_request:
        expected = topic_line(topic)
        for path, text in [(cursor_topic, cursor_text), (claude_topic, claude_text)]:
            if path.exists() and topic.rel_path in text:
                report.add("ERROR", "on-request-misclassified", path, f"on-request topic appears in topic index: {topic.rel_path}")
        if agents.exists():
            if expected not in agents_actions:
                report.add("ERROR", "index-wording-drift", agents, f"missing On-request action line: {expected}")
            if topic.rel_path in agents_topics:
                report.add("ERROR", "on-request-misclassified", agents, f"on-request topic appears in Topic-based section: {topic.rel_path}")

    for topic in topic_based + on_request:
        if copilot.exists() and f"]({topic.rel_path})" not in copilot_text:
            report.add("ERROR", "hub-coverage-gap", copilot, f"hub table does not reference canonical topic: {topic.rel_path}")


def audit_on_request_parity(report: AuditReport, on_request: list[Topic]) -> None:
    for topic in on_request:
        cursor_path = REPO_ROOT / ".cursor" / "rules" / f"{topic.stem}.mdc"
        claude_path = REPO_ROOT / ".claude" / "skills" / topic.stem / "SKILL.md"
        if not cursor_path.exists():
            report.add("ERROR", "missing-provider-view", cursor_path, "missing Cursor agent-requested rule for canonical skill")
        if not claude_path.exists():
            report.add("ERROR", "missing-provider-view", claude_path, "missing Claude skill for canonical skill")


def audit_generated_drift(report: AuditReport, outputs: dict[Path, str]) -> None:
    for path, expected in sorted(outputs.items(), key=lambda item: repo_rel(item[0])):
        actual = path.read_text(encoding="utf-8") if path.exists() else None
        if actual is None:
            report.add("ERROR", "generated-missing", path, "generated provider output is missing")
        elif actual != expected:
            report.add("ERROR", "generated-drift", path, "generated provider output differs from compiler output")

    for path in sorted(stale_generated(outputs), key=repo_rel):
        report.add("ERROR", "stale-generated", path, "generated provider output no longer has a canonical source")


def audit_gitignore(report: AuditReport) -> None:
    gitignore = REPO_ROOT / ".gitignore"
    if not gitignore.exists():
        return
    lines = {line.strip() for line in gitignore.read_text(encoding="utf-8").splitlines()}
    for entry in [".DS_Store", "Thumbs.db"]:
        if entry not in lines:
            report.add("WARN", "gitignore-hygiene", gitignore, f"missing OS noise entry: {entry}")


def build_audit_report(
    file_scoped: list[Topic],
    topic_based: list[Topic],
    on_request: list[Topic],
    outputs: dict[Path, str],
) -> AuditReport:
    report = AuditReport(findings=[])
    audit_dangling_links(report)
    audit_provider_stem_parity(report, file_scoped, topic_based, on_request)
    audit_on_request_parity(report, on_request)
    audit_scaffold_residue(report)
    audit_frontmatter(report, file_scoped, on_request)
    audit_index_wording(report, topic_based, on_request)
    audit_generated_drift(report, outputs)
    audit_gitignore(report)
    return report


def print_audit_report(report: AuditReport, *, as_json: bool = False) -> None:
    if as_json:
        print(json.dumps([finding.__dict__ for finding in report.findings], indent=2, sort_keys=True))
        return

    if not report.findings:
        print("instruction integrity audit passed")
        return

    print("instruction integrity audit findings:")
    for finding in sorted(report.findings, key=lambda item: (item.level != "ERROR", item.code, item.path, item.message)):
        print(f"  {finding.level} {finding.code} {finding.path}: {finding.message}")


def run_audit(
    file_scoped: list[Topic],
    topic_based: list[Topic],
    on_request: list[Topic],
    outputs: dict[Path, str],
    *,
    as_json: bool = False,
) -> int:
    report = build_audit_report(file_scoped, topic_based, on_request, outputs)
    print_audit_report(report, as_json=as_json)
    return 1 if report.has_errors() else 0


def run_diff(outputs: dict[Path, str]) -> int:
    printed = False
    for path, expected in sorted(outputs.items(), key=lambda item: repo_rel(item[0])):
        diff = diff_text(path, expected)
        if diff:
            printed = True
            print(diff, end="" if diff.endswith("\n") else "\n")
    for path in sorted(stale_generated(outputs), key=repo_rel):
        old = path.read_text(encoding="utf-8")
        diff = "".join(
            difflib.unified_diff(
                old.splitlines(keepends=True),
                [],
                fromfile=f"a/{repo_rel(path)}",
                tofile="/dev/null",
            )
        )
        if diff:
            printed = True
            print(diff, end="" if diff.endswith("\n") else "\n")
    if not printed:
        print("instruction sync diff is empty")
    return 0


def run_write(outputs: dict[Path, str]) -> int:
    changed: list[str] = []
    for path, expected in sorted(outputs.items(), key=lambda item: repo_rel(item[0])):
        actual = path.read_text(encoding="utf-8") if path.exists() else None
        if actual == expected:
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(expected, encoding="utf-8")
        changed.append(repo_rel(path))

    removed: list[str] = []
    for path in sorted(stale_generated(outputs), key=repo_rel):
        path.unlink()
        removed.append(repo_rel(path))
        parent = path.parent
        while parent != REPO_ROOT and parent.exists():
            try:
                parent.rmdir()
            except OSError:
                break
            parent = parent.parent

    if changed:
        print("written:")
        for item in changed:
            print(f"  {item}")
    if removed:
        print("removed stale generated files:")
        for item in removed:
            print(f"  {item}")
    if not changed and not removed:
        print("instruction sync already up to date")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail non-zero if generated outputs differ from disk")
    parser.add_argument("--diff", action="store_true", help="print unified diff without writing")
    parser.add_argument("--write", action="store_true", help="write generated files and remove stale generated files")
    parser.add_argument("--audit", action="store_true", help="run deterministic instruction integrity audit")
    parser.add_argument("--json", action="store_true", help="emit audit findings as JSON")
    parser.add_argument(
        "--inline-topic-rules",
        action="store_true",
        help="reserved for future use; topic indexes remain compact in this implementation",
    )
    args = parser.parse_args()

    if args.inline_topic_rules:
        print("--inline-topic-rules is reserved; topic-based provider indexes remain compact", file=sys.stderr)

    if args.json and (not args.audit or args.check or args.diff or args.write):
        parser.error("--json can only be used with --audit alone")

    if not (args.check or args.diff or args.write or args.audit):
        parser.error("choose at least one mode: --check, --diff, --write, or --audit")

    try:
        file_scoped, topic_based, on_request = load_topics()
        outputs = generated_outputs(file_scoped, topic_based, on_request)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2

    status = 0
    if args.diff:
        status = max(status, run_diff(outputs))
    if args.write:
        status = max(status, run_write(outputs))
        if args.check or args.audit:
            file_scoped, topic_based, on_request = load_topics()
            outputs = generated_outputs(file_scoped, topic_based, on_request)
    if args.check:
        status = max(status, run_check(outputs))
    if args.audit:
        status = max(status, run_audit(file_scoped, topic_based, on_request, outputs, as_json=args.json))
    return status


if __name__ == "__main__":
    raise SystemExit(main())
